// Generate / Regenerate a learning plan or practice quiz from the student
// page (IOLG-137). The button POSTs to the server, which runs the same CLI
// command a person would type; this script polls the job and shows its
// output while it runs, then reloads the page so the result is rendered by
// the same template as a file generated by hand.
(function () {
  function fmt(seconds) {
    const s = Math.round(seconds);
    return s < 60 ? s + " s" : Math.floor(s / 60) + " min " + (s % 60) + " s";
  }

  function wire(box) {
    const kind = box.dataset.kind;
    const student = box.dataset.student;
    const button = box.querySelector("button.generate");
    const status = box.querySelector(".generate-status");
    const bar = box.querySelector(".generate-bar");
    const log = box.querySelector(".generate-log");
    const base = "/student/" + encodeURIComponent(student) + "/generate/" + kind;
    let timer = null;

    function show(job) {
      status.textContent =
        (job.state === "running" ? "Generating, " : job.state === "done" ? "Done in " : "Failed after ") +
        fmt(job.elapsed) +
        (job.state === "running" ? ". One language-model call per attempt; the lines below are the command's own output." : ".");
      log.textContent = job.lines.join("\n");
      log.hidden = job.lines.length === 0;
      bar.hidden = job.state !== "running";
      button.disabled = job.state === "running";
    }

    function poll() {
      fetch(base + "/status")
        .then((r) => r.json())
        .then((job) => {
          show(job);
          if (job.state === "running") {
            timer = setTimeout(poll, 1500);
          } else if (job.state === "done") {
            // The file now exists; the template renders it on reload.
            window.location.reload();
          } else {
            button.textContent = button.dataset.retryLabel;
          }
        })
        .catch(() => {
          status.textContent = "Lost contact with the dashboard; reload the page.";
          button.disabled = false;
        });
    }

    button.addEventListener("click", () => {
      button.disabled = true;
      status.textContent = "Starting…";
      fetch(base, { method: "POST" })
        .then((r) => {
          if (r.status === 409) {
            status.textContent = "Already running.";
            poll();
            return null;
          }
          if (!r.ok) throw new Error("HTTP " + r.status);
          return r.json();
        })
        .then((job) => {
          if (job) {
            show(job);
            timer = setTimeout(poll, 1000);
          }
        })
        .catch((e) => {
          status.textContent = "Could not start: " + e.message;
          button.disabled = false;
        });
    });

    // A job may already be running from before a reload.
    if (box.dataset.running === "true") {
      button.disabled = true;
      poll();
    }
  }

  document.querySelectorAll(".generate-box").forEach(wire);
})();
